import React from 'react';
import { useSimulation } from '../context/SimulationContext';
import { MapContainer, TileLayer, CircleMarker, Tooltip, Polyline, Popup } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';
import './Components.css';

const MapPanel = ({ fullScreen }) => {
  const { mode, metrics } = useSimulation();

  // Coordinates
  const ALMATY_CENTER = [43.238949, 76.889709];

  // Helper to slice a route into many tiny segments for 2GIS realistic traffic effect
  const generateTrafficSegments = (route, overallTrafficPercent) => {
    const segments = [];
    for (let i = 0; i < route.length - 1; i++) {
        // Interpolate points between major route nodes to create more segments
        const p1 = route[i];
        const p2 = route[i+1];

        const subSteps = 4; // split each leg into 4 sub-segments
        for (let j = 0; j < subSteps; j++) {
            const lat1 = p1[0] + (p2[0] - p1[0]) * (j / subSteps);
            const lng1 = p1[1] + (p2[1] - p1[1]) * (j / subSteps);
            const lat2 = p1[0] + (p2[0] - p1[0]) * ((j + 1) / subSteps);
            const lng2 = p1[1] + (p2[1] - p1[1]) * ((j + 1) / subSteps);

            // Congestion logic
            const randomVariance = (Math.random() * 40) - 20; 
            const localTraffic = overallTrafficPercent + randomVariance;
            let color = '#2ed573'; // Green (default)
            if (localTraffic > 60) color = '#ffa502'; // Yellow/Orange
            if (localTraffic > 85) color = '#ff4757'; // Red
            if (localTraffic > 98) color = '#8b0000'; // Dark Red (Deadlock)

            if (mode === 'smog') {
                color = Math.random() > 0.5 ? '#ff4757' : '#8b0000';
            }

            segments.push({
                positions: [[lat1, lng1], [lat2, lng2]],
                color
            });
        }
    }
    return segments;
  };

  const alFarabiRouteBase = [
    [43.2081, 76.8623], [43.2145, 76.8975], [43.2201, 76.9365], [43.2268, 76.9642]
  ];

  const abayRouteBase = [
    [43.2405, 76.8665], [43.2415, 76.9200], [43.2435, 76.9575]
  ];

  const alFarabiSegments = generateTrafficSegments(alFarabiRouteBase, metrics.transport.alfarabi);
  const abaySegments = generateTrafficSegments(abayRouteBase, metrics.transport.abay);

  return (
    <div className={`glass-panel ${fullScreen ? '' : 'animate-slide-up'}`} style={{ 
      gridArea: 'map', 
      padding: 0, 
      overflow: 'hidden', 
      position: 'relative', 
      border: fullScreen ? 'none' : '1px solid #333',
      height: fullScreen ? '100vh' : 'auto',
      zIndex: 1
    }}>

      {/* Title overlay */}
      <div style={{ position: 'absolute', top: 20, left: 20, zIndex: 1000, background: '#000', padding: '8px 16px', borderRadius: '4px', border: '1px solid #333', pointerEvents: 'none' }}>
        <h2 className="brand-font" style={{ fontSize: '14px', fontWeight: 600, color: '#fff' }}>GPS-СИСТЕМА: АЛМАТЫ</h2>
      </div>

      <MapContainer 
        center={ALMATY_CENTER} 
        zoom={12} 
        style={{ height: '100%', width: '100%', background: '#000', filter: 'grayscale(100%) invert(100%)' }}
        zoomControl={false}
      >
        <TileLayer
          url="https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png"
          attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OSM</a>'
        />

        {metrics.incidents.map(inc => (
          <CircleMarker 
            key={inc.id}
            center={inc.coords} 
            radius={inc.category === 'ДТП' ? 12 : 8} 
            pathOptions={{ 
              color: inc.color, 
              fillColor: inc.color, 
              fillOpacity: 1,
              weight: 2
            }}
          >
            <Tooltip direction="top" offset={[0, -10]}>
              <div style={{ fontWeight: 600, color: '#111', textTransform: 'uppercase' }}>
                {inc.title}
              </div>
            </Tooltip>

            <Popup className="tactical-popup">
              <div style={{ background: '#000', color: '#fff', padding: '8px', border: `1px solid ${inc.color}`, minWidth: '220px', fontSize: '12px', fontFamily: 'monospace' }}>
                <div style={{ borderBottom: '1px solid #333', paddingBottom: '4px', marginBottom: '8px', color: inc.color, fontWeight: 'bold' }}>
                  [ID: {inc.id.toUpperCase()}] {inc.title}
                </div>
                <div style={{ marginBottom: '4px' }}><strong>ВРЕМЯ:</strong> {inc.time}</div>
                <div style={{ marginBottom: '4px' }}><strong>ЛОКАЦИЯ:</strong> {inc.locationName}</div>
                <div style={{ marginBottom: '4px' }}><strong>РАЙОН:</strong> {inc.area}</div>
                <div style={{ marginBottom: '8px' }}><strong>GPS:</strong> {inc.coords[0].toFixed(4)}, {inc.coords[1].toFixed(4)}</div>
                <div style={{ color: '#aaa', lineHeight: 1.4, borderTop: '1px solid #333', paddingTop: '8px' }}>
                  {inc.description}
                </div>
              </div>
            </Popup>
          </CircleMarker>
        ))}

        {alFarabiSegments.map((seg, idx) => (
            <Polyline key={`alf_${idx}`} positions={seg.positions} pathOptions={{ color: seg.color, weight: 5, opacity: 0.9 }}>
               <Popup>
                <div style={{ background: '#000', color: '#fff', padding: '8px', fontFamily: 'monospace', border: `1px solid ${seg.color}` }}>
                <strong>МАГИСТРАЛЬ: АЛЬ-ФАРАБИ (УЧАСТОК #{idx})</strong><br/>
                ЛОКАЛЬНАЯ НАГРУЗКА: {seg.color === '#ff4757' ? 'ВЫСОКАЯ' : seg.color === '#8b0000' ? 'КРИТИЧЕСКАЯ' : 'НОРМА'}
                </div>
              </Popup>
            </Polyline>
        ))}

        {abaySegments.map((seg, idx) => (
            <Polyline key={`ab_${idx}`} positions={seg.positions} pathOptions={{ color: seg.color, weight: 4, opacity: 0.8 }} />
        ))}

      </MapContainer>
    </div>
  );
};

export default MapPanel;

