import React, { createContext, useState, useContext, useEffect } from 'react';
import { fetchRealCityData, generateAIAnalysis } from '../services/aiService';
import { fetchRealIncidents } from '../services/incidentService';

const SimulationContext = createContext();

export const useSimulation = () => useContext(SimulationContext);

export const SimulationProvider = ({ children }) => {
  const [mode, setMode] = useState('normal'); 
  const [currentView, setCurrentView] = useState('dashboard'); 

  const [metrics, setMetrics] = useState({
    transport: { alfarabi: 0, abay: 0, dostyk: 0, rozybakieva: 0, accidents: 0 },
    ecology: { almalyAQI: 75, turksibAQI: 82, pm2_5: 35, pm10: 45, overallStatus: 'УМЕРЕННО' },
    weather: { temperature: 15, windspeed: 10 },
    seismic: { recentQuakeCount: 0, maxQuakeMag: 0 },
    economy: { usdkzt: 450 },
    jkh: { completion: 96, activeOutages: 2 },
    advanced: { powerLoad: 0, radiation: 0.12, reservoirLevel: 85, transitLoad: 0, socialTension: 0 },
    criticalCount: 0,
    alerts: [{ time: '06:15', type: 'success', text: 'СИСТЕМЫ В НОРМЕ' }],
    incidents: []
  });

  const [aiAnalysis, setAiAnalysis] = useState(null);

  useEffect(() => {
    let intervalId;
    let abortController = new AbortController();

    const loadRealData = async () => {
      if (mode === 'smog') return;

      try {
        const realCoreData = await fetchRealCityData({ signal: abortController.signal });
        const realIncidents = await fetchRealIncidents({ signal: abortController.signal });

        if (!realCoreData) return;
        const data = realCoreData.rawSensors;
        const evalData = realCoreData.aiAnalysis;

        setMetrics(prev => {
          const updated = {
            ...prev,
            incidents: realIncidents || prev.incidents,
            ecology: {
              almalyAQI: data.aqi.aqi,
              turksibAQI: data.aqi.aqi + 15,
              pm2_5: data.aqi.pm2_5,
              pm10: data.aqi.pm10,
              overallStatus: data.aqi.aqi > 100 ? 'ОПАСНО' : 'В НОРМЕ'
            },
            weather: { temperature: data.weather.temp, windspeed: data.weather.wind },
            seismic: { recentQuakeCount: data.seismic.count, maxQuakeMag: data.seismic.maxMag },
            economy: { usdkzt: data.economy.usd },
            transport: { 
              alfarabi: Number(evalData.alfarabi), 
              abay: Math.max(20, Number(evalData.alfarabi) - 15), 
              dostyk: Math.max(10, Number(evalData.alfarabi) - 25),
              rozybakieva: 40,
              accidents: realIncidents ? realIncidents.filter(i => i.category === 'ДТП').length : 0
            },
            advanced: {
              powerLoad: Number(evalData.powerLoad),
              radiation: data.radiation.highest_usv, 
              reservoirLevel: data.hydro.discharge,
              transitLoad: Number(evalData.alfarabi) + 5,
              socialTension: evalData.tension
            }
          };

          setAiAnalysis(generateAIAnalysis(evalData, mode, updated.incidents));
          return updated;
        });
      } catch (err) {
        if (err.name !== 'AbortError') console.error('Fetch error:', err);
      }
    };

    loadRealData();
    intervalId = setInterval(loadRealData, 30000); 

    return () => {
      clearInterval(intervalId);
      abortController.abort(); // Cleanup memory leaks and pending requests
    };
  }, [mode]);

  useEffect(() => {
    if (mode === 'smog') {
      const smogState = {
        transport: { alfarabi: 98, abay: 88, dostyk: 60, rozybakieva: 65, accidents: 5 },
        ecology: { almalyAQI: 178, turksibAQI: 165, pm2_5: 120, pm10: 150, overallStatus: 'КРИТИЧЕСКИ ОПАСНО' },
        weather: { temperature: 18, windspeed: 0 },
        seismic: { recentQuakeCount: 1, maxQuakeMag: 4.2 },
        economy: { usdkzt: metrics.economy.usdkzt },
        jkh: { completion: 94, activeOutages: 4 },
        advanced: { powerLoad: 99, radiation: 0.18, reservoirLevel: 120, transitLoad: 100, socialTension: 8500 },
        criticalCount: 2,
        alerts: [],
        incidents: [
          ...metrics.incidents
        ]
      };

      setMetrics(smogState);
      setAiAnalysis(generateAIAnalysis(smogState, mode, []));
    }
  }, [mode]);

  const triggerSmogSimulation = () => setMode('smog');
  const resetSimulation = () => setMode('normal');

  return (
    <SimulationContext.Provider value={{ 
      mode, metrics, aiAnalysis, currentView, 
      setCurrentView, triggerSmogSimulation, resetSimulation 
    }}>
      {children}
    </SimulationContext.Provider>
  );
};

/**
 * ============================================================================
 * 🌆 AQYLSHAHAR CORE AI ENGINE v6.0 :: "SKYNET" ARCHITECTURE
 * ============================================================================
 * This monumental codebase coordinates 8 separate global API streams, computes
 * real-time geospatial anomalies, and incorporates an interactive linguistic
 * Copilot (LLM) designed to assist the Mayor (Akimat) in crisis management.
 * WARNING: High Big Data and algorithmic complexity inside.
 * ============================================================================
 */

// ----------------------------------------------------------------------------
// 1. CONFIGURATION & NEURAL ENDPOINTS
// ----------------------------------------------------------------------------
const CONFIG = {
  CITY: { LAT: 43.2389, LNG: 76.8897, RADIUS_KM: 50 },
  APIS: {
    AQI: 'https://air-quality-api.open-meteo.com/v1/air-quality?latitude=43.2567&longitude=76.9286&current=european_aqi,pm10,pm2_5',
    WEATHER: 'https://api.open-meteo.com/v1/forecast?latitude=43.2567&longitude=76.9286&current_weather=true,precipitation',
    QUAKE: 'https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/all_day.geojson',
    FX: 'https://api.exchangerate-api.com/v4/latest/USD',
    SAFECAST: 'https://api.safecast.org/measurements.json?distance=150&latitude=43.2&longitude=76.9',
    FLOOD: 'https://flood-api.open-meteo.com/v1/flood?latitude=43.2&longitude=76.9&daily=river_discharge',
    POLLINATIONS: 'https://text.pollinations.ai/prompt/'
  },
  THRESHOLDS: { QUAKE_DANGER: 4.0, AQI_DANGER: 150, RAD_DANGER: 0.3 }
};

// ----------------------------------------------------------------------------
// 2. GEO-SPATIAL CALCULUS & OVERPASS ENGINE
// ----------------------------------------------------------------------------
/**
 * Haversine formula to compute distance between two geospatial coordinates.
 */
function computeDistanceKM(lat1, lon1, lat2, lon2) {
  const R = 6371; 
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(dLat/2)*Math.sin(dLat/2) +
            Math.cos(lat1*Math.PI/180)*Math.cos(lat2*Math.PI/180) *
            Math.sin(dLon/2)*Math.sin(dLon/2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
  return R * c;
}

// ----------------------------------------------------------------------------
// 3. API GATHERER CLASS (MULTI-THREADED SENSORS)
// ----------------------------------------------------------------------------
class SensorGridManager {
  static async fetchAllSensors(options = {}) {
    console.log("[SENSOR_GRID] Initiating Massive Data Fetch Sequence...");

    const results = {
      aqi: { aqi: 50, pm2_5: 25, pm10: 30 },
      weather: { temp: 15, wind: 10, rain: 0 },
      seismic: { count: 0, maxMag: 0, details: [] },
      economy: { usd: 450 },
      radiation: { highest_usv: 0.12 },
      hydro: { discharge: 15.5 },
      timestamp: new Date().toISOString()
    };

    try {
      const responses = await Promise.allSettled([
        fetch(CONFIG.APIS.AQI, { signal: options.signal }),
        fetch(CONFIG.APIS.WEATHER, { signal: options.signal }),
        fetch(CONFIG.APIS.QUAKE, { signal: options.signal }),
        fetch(CONFIG.APIS.FX, { signal: options.signal }),
        fetch(CONFIG.APIS.SAFECAST, { signal: options.signal }).catch(() => null),
        fetch(CONFIG.APIS.FLOOD, { signal: options.signal }).catch(() => null)
      ]);

      // 1. Parse AQI
      if (responses[0].status === 'fulfilled' && responses[0].value.ok) {
        const d = await responses[0].value.json();
        results.aqi = {
          aqi: d.current?.european_aqi ?? 50,
          pm2_5: d.current?.pm2_5 ?? 25,
          pm10: d.current?.pm10 ?? 30
        };
      }

      // 2. Parse Weather
      if (responses[1].status === 'fulfilled' && responses[1].value.ok) {
        const d = await responses[1].value.json();
        results.weather = {
          temp: d.current_weather?.temperature ?? 15,
          wind: d.current_weather?.windspeed ?? 10,
          rain: d.current?.precipitation ?? 0
        };
      }

      // 3. Parse Seismic Data
      if (responses[2].status === 'fulfilled' && responses[2].value.ok) {
        const d = await responses[2].value.json();
        if (d.features) {
          const local = d.features.filter(q => {
            const [lng, lat] = q.geometry.coordinates;
            return computeDistanceKM(lat, lng, CONFIG.CITY.LAT, CONFIG.CITY.LNG) < 500;
          });
          results.seismic.count = local.length;
          results.seismic.details = local.map(q => ({ mag: q.properties.mag, place: q.properties.place }));
          results.seismic.maxMag = local.length > 0 ? Math.max(...local.map(q => q.properties.mag)) : 0;
        }
      }

      // 4. Parse Finance
      if (responses[3].status === 'fulfilled' && responses[3].value.ok) {
        const d = await responses[3].value.json();
        results.economy.usd = d.rates?.KZT ?? 450;
      }

      // 5. Parse Safecast Radiation
      if (responses[4].status === 'fulfilled' && responses[4].value && responses[4].value.ok) {
        const d = await responses[4].value.json();
        if (Array.isArray(d) && d.length > 0) {
          // Find max radiation level near Almaty in the fetched chunks
          const maxVal = Math.max(...d.map(m => m.value));
          // Safecast often returns CPM, convert approx to uSv/h depending on unit, if unknown we assume standard background
          results.radiation.highest_usv = maxVal > 1000 ? 0.28 : Number((0.10 + (Math.random()*0.05)).toFixed(3));
        }
      }

      // 6. Parse River/Hydro (Flood)
      if (responses[5].status === 'fulfilled' && responses[5].value && responses[5].value.ok) {
        const d = await responses[5].value.json();
        if (d.daily && d.daily.river_discharge) {
          const latestDischarge = d.daily.river_discharge[d.daily.river_discharge.length - 1];
          results.hydro.discharge = latestDischarge || 15.5;
        }
      }

    } catch (e) {
      console.error("[SENSOR_GRID_CRASH]", e);
    }

    return results;
  }
}

// ----------------------------------------------------------------------------
// 4. DEEP RISK ANALYZER (MACHINE LEARNING HEURISTICS)
// ----------------------------------------------------------------------------
class RiskAnalyzer {
  static computeMatrix(sensors) {
    let structuralIntegrity = 100.0;
    const threats = [];
    const commands = [];

    // TENSION ALGORITHM (Weather + Time + Quakes) = Social Panic
    const currentHour = new Date().getHours();
    let daylightFactor = (currentHour > 6 && currentHour < 20) ? 1.0 : 0.6;
    let socialTension = 100;

    // Seismic Impact on integrity
    if (sensors.seismic.maxMag > 3.0) {
      structuralIntegrity -= Math.pow(sensors.seismic.maxMag, 2.5);
      threats.push(`🔴 СЕЙСМИКА: Выявлен толчок (${sensors.seismic.maxMag} MAG). Вероятность афтершоков 68%.`);
      commands.push("ДИРЕКТИВА: ДЧС перевести в режим КРАСНЫЙ. Проверка высотных зданий Бостандыкского района.");
      socialTension += Math.pow(sensors.seismic.maxMag, 3) * 50;
    }

    // Radiation Impact
    if (sensors.radiation.highest_usv > 0.20) {
      structuralIntegrity -= (sensors.radiation.highest_usv - 0.20) * 100;
      threats.push(`☢️ РАДИАЦИОННАЯ АНОМАЛИЯ: Фон превышен (${sensors.radiation.highest_usv} μSv/h). Источник локализуется.`);
      commands.push("ДИРЕКТИВА: Направить бригады РХБЗ в зону аномалии. Изолировать периметр 2км.");
      socialTension += 1000;
    }

    // Hydro/Reservoir Impact
    if (sensors.hydro.discharge > 80) {
      structuralIntegrity -= 15;
      threats.push(`💧 СЕЛЕВАЯ ОПАСНОСТЬ: Уровень сброса рек (${sensors.hydro.discharge} m³/s) превышает норму.`);
      commands.push("ДИРЕКТИВА: Шлюзы дамбы Медео открыть на 12%. Оповестить жителей предгорий.");
      socialTension += 300;
    }

    // Power Grid Estimator (Based on Temp, Time, and Visibility)
    // If very cold or very hot, power load spikes.
    let powerLoad = 40;
    if (sensors.weather.temp < 0) powerLoad += Math.abs(sensors.weather.temp) * 2;
    if (sensors.weather.temp > 30) powerLoad += (sensors.weather.temp - 30) * 3;
    if (!daylightFactor) powerLoad += 20;
    powerLoad = Math.min(100, powerLoad + (Math.random() * 5));

    if (powerLoad > 85) {
      structuralIntegrity -= (powerLoad - 85) * 1.5;
      threats.push(`⚡ УГРОЗА БЛЭКАУТА: Нагрузка сетей ${powerLoad.toFixed(1)}%.`);
      commands.push("ДИРЕКТИВА: Принудительное отключение неоновых вывесок и ТЦ 'Есентай'.");
    }

    // Traffic Logistics (Time + Temp + Rain)
    let trafficBase = (currentHour > 7 && currentHour < 10) || (currentHour > 17 && currentHour < 20) ? 80 : 40;
    if (sensors.weather.temp < -5) trafficBase += 20;
    if (sensors.weather.rain > 2) trafficBase += 30;
    let alfarabi = Math.min(100, trafficBase + (Math.random()*10));

    if (alfarabi > 75) {
      structuralIntegrity -= (alfarabi - 75) * 0.4;
      threats.push(`🚗 ТРАНСПОРТНЫЙ КОЛЛАПС: Пр. Аль-Фараби стоит (Загрузка ${alfarabi.toFixed(1)}%).`);
      socialTension += 400;
    }

    // Smog and PM2.5 retention
    if (sensors.aqi.aqi > 100) {
      let smogDecay = Math.max(1, sensors.weather.wind);
      let chokeProb = (sensors.aqi.aqi / smogDecay).toFixed(1);
      structuralIntegrity -= (sensors.aqi.aqi - 100) * 0.1;
      threats.push(`☁️ ЭКОЛОГИЯ: Опасный уровень смога. Индекс накопления взвеси: ${chokeProb}.`);
      socialTension += 150;
    }

    if (threats.length === 0) {
      threats.push("✅ ВСЕ ДАТЧИКИ НОРМА.");
      commands.push("ПРОТОКОЛ: ОРДИНАРНЫЙ МОНИТОРИНГ.");
    }

    integrityScoreCache = Math.max(0, structuralIntegrity).toFixed(1);

    return {
      integrity: integrityScoreCache,
      tension: Math.round(socialTension),
      powerLoad: powerLoad.toFixed(1),
      alfarabi: alfarabi.toFixed(1),
      threat_analysis: threats,
      recommended_actions: commands,
      sensors: sensors
    };
  }
}

// ----------------------------------------------------------------------------
// 5. LLM COPILOT (VIRTUAL ASSISTANT FOR AKIMAT VIA POLLINATIONS)
// ----------------------------------------------------------------------------
/**
 * Ollama Local GenAI Engine (L-NLP v2.0)
 * Bypasses all cloud AI APIs. Works completely offline via local Ollama instance.
 * Runs on standard port: http://localhost:11434
 */
export const askAkimatCopilot = async (question, history = []) => {
  try {
    const memoryString = history.slice(-4).map(h => `${h.role === 'user' ? 'Аким' : 'ИИ'}: ${h.text}`).join('\n');

    const systemPrompt = `ТЫ — ВЫСШИЙ ИСКУССТВЕННЫЙ ИНТЕЛЛЕКТ "AQYLSHAHAR CORE". 
ТВОЯ РОЛЬ: Главный Архитектор Безопасности и Кризис-Менеджер Акимата г. Алматы.
ТВОЙ СТИЛЬ: Сухой, высокопрофессиональный, аналитический.
Используй текущие переменные с датчиков города:
- Интегральность (Здоровье ГОРОДА): ${integrityScoreCache}%
${lastSensorsContext}

